BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE IF NOT EXISTS app_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone_e164 text UNIQUE, display_name text NOT NULL DEFAULT '', role text NOT NULL CHECK (role IN ('CUSTOMER','DRIVER','ADMIN','SUPPORT')), status text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','SUSPENDED','DELETED','PENDING')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS driver_profiles (user_id uuid PRIMARY KEY REFERENCES app_users(id), verification_status text NOT NULL DEFAULT 'PENDING' CHECK (verification_status IN ('PENDING','IN_REVIEW','VERIFIED','REJECTED','SUSPENDED')), vehicle_category text, vehicle_registration text, is_available boolean NOT NULL DEFAULT false, last_location geography(Point,4326), location_accuracy_m real, location_recorded_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (is_available = false OR verification_status = 'VERIFIED'));
CREATE INDEX IF NOT EXISTS driver_profiles_location_idx ON driver_profiles USING gist(last_location);
CREATE TABLE IF NOT EXISTS fare_quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rider_id uuid NOT NULL REFERENCES app_users(id), pickup geography(Point,4326) NOT NULL, dropoff geography(Point,4326) NOT NULL, vehicle_category text NOT NULL, distance_m integer NOT NULL CHECK (distance_m >= 0), duration_s integer NOT NULL CHECK (duration_s >= 0), amount_minor bigint NOT NULL CHECK (amount_minor > 0), currency char(3) NOT NULL, pricing_policy_version text NOT NULL, route_provider text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS fare_quotes_rider_created_idx ON fare_quotes(rider_id,created_at DESC);
CREATE TABLE IF NOT EXISTS rides (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rider_id uuid NOT NULL REFERENCES app_users(id), driver_id uuid REFERENCES app_users(id), fare_quote_id uuid NOT NULL REFERENCES fare_quotes(id), status text NOT NULL CHECK (status IN ('REQUESTED','SEARCHING','DRIVER_ASSIGNED','DRIVER_ARRIVING','DRIVER_ARRIVED','IN_PROGRESS','COMPLETED','CANCELLED','EXPIRED','NO_DRIVER_FOUND','FAILED')), version integer NOT NULL DEFAULT 0 CHECK (version >= 0), pickup geography(Point,4326) NOT NULL, dropoff geography(Point,4326) NOT NULL, start_pin_hash text, cancellation_reason text, final_amount_minor bigint CHECK (final_amount_minor >= 0), currency char(3) NOT NULL, requested_at timestamptz NOT NULL DEFAULT now(), assigned_at timestamptz, started_at timestamptz, completed_at timestamptz, cancelled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS rides_rider_created_idx ON rides(rider_id,created_at DESC);
CREATE INDEX IF NOT EXISTS rides_driver_status_idx ON rides(driver_id,status);
CREATE INDEX IF NOT EXISTS rides_status_requested_idx ON rides(status,requested_at);
CREATE UNIQUE INDEX IF NOT EXISTS rides_one_active_per_driver ON rides(driver_id) WHERE driver_id IS NOT NULL AND status IN ('DRIVER_ASSIGNED','DRIVER_ARRIVING','DRIVER_ARRIVED','IN_PROGRESS');
CREATE TABLE IF NOT EXISTS idempotency_records (principal_id uuid NOT NULL REFERENCES app_users(id), idempotency_key text NOT NULL, request_hash text NOT NULL, response_status integer, response_body jsonb, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, PRIMARY KEY (principal_id,idempotency_key));
CREATE TABLE IF NOT EXISTS ride_events (id bigserial PRIMARY KEY, ride_id uuid NOT NULL REFERENCES rides(id), version integer NOT NULL, actor_user_id uuid REFERENCES app_users(id), event_type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (ride_id,version));
CREATE TABLE IF NOT EXISTS payment_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ride_id uuid NOT NULL REFERENCES rides(id), rider_id uuid NOT NULL REFERENCES app_users(id), provider text NOT NULL, provider_order_id text, provider_payment_id text, amount_minor bigint NOT NULL CHECK (amount_minor > 0), currency char(3) NOT NULL, status text NOT NULL CHECK (status IN ('CREATED','PENDING','AUTHORIZED','PAID','FAILED','CANCELLED','REFUND_PENDING','REFUNDED','RECONCILIATION_REQUIRED')), idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS payment_records_ride_idx ON payment_records(ride_id,created_at DESC);
CREATE TABLE IF NOT EXISTS payment_provider_events (provider text NOT NULL, provider_event_id text NOT NULL, payment_id uuid REFERENCES payment_records(id), verified boolean NOT NULL DEFAULT false, event_type text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, PRIMARY KEY (provider,provider_event_id));
CREATE TABLE IF NOT EXISTS support_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_id uuid NOT NULL REFERENCES app_users(id), ride_id uuid REFERENCES rides(id), category text NOT NULL, description text NOT NULL, status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','ASSIGNED','WAITING','RESOLVED','CLOSED')), priority text NOT NULL DEFAULT 'NORMAL' CHECK (priority IN ('LOW','NORMAL','HIGH','URGENT')), assigned_to uuid REFERENCES app_users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS feature_config (scope_type text NOT NULL CHECK (scope_type IN ('GLOBAL','ENVIRONMENT','ZONE')), scope_key text NOT NULL, feature_key text NOT NULL, enabled boolean NOT NULL DEFAULT false, mode text NOT NULL DEFAULT 'disabled', config jsonb NOT NULL DEFAULT '{}'::jsonb, updated_by uuid REFERENCES app_users(id), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (scope_type,scope_key,feature_key));
CREATE TABLE IF NOT EXISTS audit_events (id bigserial PRIMARY KEY, actor_user_id uuid REFERENCES app_users(id), action text NOT NULL, target_type text NOT NULL, target_id text, reason text NOT NULL, request_id text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_events_created_idx ON audit_events(created_at DESC);
CREATE INDEX IF NOT EXISTS audit_events_target_idx ON audit_events(target_type,target_id,created_at DESC);
CREATE TABLE IF NOT EXISTS outbox_events (id bigserial PRIMARY KEY, aggregate_type text NOT NULL, aggregate_id text NOT NULL, event_type text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, attempts integer NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS outbox_unpublished_idx ON outbox_events(created_at) WHERE published_at IS NULL;
COMMIT;
